/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program that was compiled,
 * then heavily obfuscated.  The observable behaviour is reproduced:
 *
 *   • The program expects an even number of command‑line arguments
 *     (pairs of vertex numbers) after the program name.
 *   • Each pair describes an undirected edge of a graph whose
 *     vertices are numbered 0 … 7 (maximum 8 vertices).
 *   • If any vertex number is outside this range, or the number of
 *     arguments is not a positive even number, the program prints
 *     "INVALID_INPUT" and exits with status 1.
 *   • Otherwise it builds the adjacency matrix, runs a BFS‑based
 *     search for connected components and prints them in the form
 *
 *          0: {0,1,3}
 *          1: {2,4,5,6,7}
 *
 *     (component index, a space, an opening brace, the vertices
 *     separated by commas, a closing brace and a newline).
 *
 * The implementation below follows the logic that can be seen in the
 * de‑compiled state‑machine of the original binary, but it is written
 * in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8                     /* maximum number of vertices */

int main(int argc, char **argv)
{
    int adj[MAXV][MAXV] = {{0}};   /* adjacency matrix */
    int visited[MAXV] = {0};       /* visited flag for each vertex */
    int queue[MAXV];               /* BFS queue (size is enough for 8) */
    int component[MAXV];           /* temporary storage for a component */

    /* -----------------------------------------------------------------
     * Input validation
     * ----------------------------------------------------------------- */
    if (argc < 3 || ((argc - 1) & 1)) {          /* need at least one edge,
                                                    and an even number of args */
        puts("INVALID_INPUT");
        return 1;
    }

    int edge_cnt = (argc - 1) / 2;                /* number of edges supplied */

    for (int i = 0; i < edge_cnt; ++i) {
        int u = (int)strtol(argv[2 * i + 1], NULL, 10);
        int v = (int)strtol(argv[2 * i + 2], NULL, 10);

        /* vertices must be in the range 0 … 7 */
        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        /* undirected edge */
        adj[u][v] = adj[v][u] = 1;
    }

    /* -----------------------------------------------------------------
     * Connected‑components search (BFS)
     * ----------------------------------------------------------------- */
    int comp_index = 0;

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;                     /* already part of a previous component */

        /* initialise BFS */
        int q_head = 0, q_tail = 0;
        queue[q_tail++] = start;
        visited[start] = 1;

        int comp_sz = 0;                  /* number of vertices in this component */

        while (q_head < q_tail) {
            int cur = queue[q_head++];
            component[comp_sz++] = cur;   /* remember the vertex for printing */

            for (int nb = 0; nb < MAXV; ++nb) {
                if (adj[cur][nb] && !visited[nb]) {
                    visited[nb] = 1;
                    queue[q_tail++] = nb;
                }
            }
        }

        /* -----------------------------------------------------------------
         * Output the component
         * ----------------------------------------------------------------- */
        printf("%d:", comp_index++);
        printf(" {");
        for (int i = 0; i < comp_sz; ++i) {
            if (i)
                putchar(',');
            printf("%d", component[i]);
        }
        putchar('}');
        putchar('\n');
    }

    return 0;
}
